-- =============================================================================
-- Demo plant: Cypress Bend Rice Mill (fictional company, people and records).
-- Local development and sales-demo data only. Loaded after seed.sql.
--
-- Shared ids used by the module seed files in this folder:
--   tenant            20000000-0000-4000-8000-000000000100
--   location          20000000-0000-4000-8000-000000000300   (Cypress Bend Main Plant)
--   division          20000000-0000-4000-8000-000000000200   (Operations)
--   admin user        20000000-0000-4000-8000-000000000001   (admin@forge2.local, Company Owner)
--   demo user         20000000-0000-4000-8000-000000000002   (user@forge2.local, "Forge Demo User")
--   departments       Milling ..2001, Maintenance ..2002, Shipping & Receiving ..2003,
--                     Drying & Storage 60000000-..-000000002004, Quality & Lab ..2005,
--                     Safety & Environmental ..2006
--   people            60000000-0000-4000-8000-0000000030NN (NN = 01..24, see below)
-- =============================================================================

update public.organizations
set name = 'Cypress Bend Rice Mill', updated_at = now()
where id = '20000000-0000-4000-8000-000000000100';

update public.locations
set name = 'Cypress Bend Main Plant', code = 'CBM', updated_at = now()
where id = '20000000-0000-4000-8000-000000000300';

update public.divisions
set name = 'Operations', code = 'OPS', updated_at = now()
where id = '20000000-0000-4000-8000-000000000200';

-- Departments (three exist from the port seed).
insert into public.forge_departments (id, organization_id, location_id, division_id, name, code, description, created_by, updated_by)
values
  ('60000000-0000-4000-8000-000000002004','20000000-0000-4000-8000-000000000100','20000000-0000-4000-8000-000000000300','20000000-0000-4000-8000-000000000200','Drying & Storage','DRY','Receiving pit, dryers, bins and grain storage.','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001'),
  ('60000000-0000-4000-8000-000000002005','20000000-0000-4000-8000-000000000100','20000000-0000-4000-8000-000000000300','20000000-0000-4000-8000-000000000200','Quality & Lab','QC','Grading, moisture testing and product quality.','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001'),
  ('60000000-0000-4000-8000-000000002006','20000000-0000-4000-8000-000000000100','20000000-0000-4000-8000-000000000300','20000000-0000-4000-8000-000000000200','Safety & Environmental','EHS','Plant safety, training and environmental compliance.','20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001')
on conflict (id) do update
set name = excluded.name, code = excluded.code, description = excluded.description, is_active = true, updated_at = now();

update public.forge_departments
set description = case code
  when 'MILL' then 'Hulling, whitening, grading and milling lines.'
  when 'MAINT' then 'Mechanical and electrical maintenance for the whole plant.'
  when 'SHIP' then 'Bagging, warehouse, truck and rail loadout.'
  else description end,
  updated_at = now()
where organization_id = '20000000-0000-4000-8000-000000000100' and code in ('MILL', 'MAINT', 'SHIP');

